mapper.insert:
insert into _volunteer (
    voTitle, voLocation, voTarget, voContent, voCapacity,
    voManager, voContact, voStartDate, voEndDate,
    voRecruitStart, voRecruitEnd, status
) values (
    #{voTitle}, #{voLocation}, #{voTarget}, #{voContent}, #{voCapacity},
    #{voManager}, #{voContact}, #{voStartDate}, #{voEndDate},
    #{voRecruitStart}, #{voRecruitEnd}, #{status}
)

mapper.select:
select 
    v.*,
    (select count(*) from _volunteer_apply 
     where volunteerId = v.voId and status != 'CANCELED') as applicationCount
from _volunteer v
where v.status = 'active'

    and v.recruitStatus = #{recruitStatus}


    and (v.voTitle like concat('%', #{keyword}, '%') 
    or v.voLocation like concat('%', #{keyword}, '%'))


    and v.voRecruitEnd >= #{startDate}


    and v.voRecruitStart <= #{endDate}

order by v.voRegDate desc

    limit #{start}, #{size}

mapper.insert:
insert into _volunteer_apply (
    volunteerId, voApplicant, voBirth, voTel, voEmail,
    voExperience, voReason, voAgree, status
) values (
    #{volunteerId}, #{voApplicant}, #{voBirth}, #{voTel}, #{voEmail},
    #{voExperience}, #{voReason}, #{voAgree}, #{status}
)

mapper.update:
update _volunteer_apply
set 
    status = #{status}

        , cancelReason = #{cancelReason}       
        , cancelReasonDetail = #{cancelReasonDetail} 

    , voUpdateDate = CURRENT_TIMESTAMP
where voId = #{voId}

mapper.select:
select a.*, v.voTitle, v.voStartDate, v.voEndDate, v.voManager, v.voContact, v.voLocation, v.voContent from _volunteer_apply a join _volunteer v ON a.volunteerId = v.voId where 1=1
and a.volunteerId = #{volunteerId}
and a.status = #{status}
order by a.voRegDate desc

select count(*)
from _volunteer v
where v.status = 'active'

    and v.recruitStatus = #{recruitStatus}


    and (
        v.voTitle like concat('%', #{keyword}, '%')
        OR v.voLocation like concat('%', #{keyword}, '%')
    )


    and v.voRecruitEnd >= #{startDate}


    and v.voRecruitStart <= #{endDate}
